{
  "description": "One static 16x16 pixel-art UI Ready status icon conveying successful completion: visibly use a check mark with asymmetrical arms. Transparent background. Readable silhouette at native 1x and 3x nearest-neighbor scale on dark navy #172336. Use the existing UI cool blue accent direction; #70b9ed is a color cue, not an exact required palette. Deliberate clean pixel clusters and edges. No fixed palette or binary-alpha restriction. Proposed representative sample before expanding the Working, Retry and Paused family; no approved style reference exists yet. Transparent background permits an intentional foreground plate or badge and authored partial-alpha subject edges if the check remains readable. Cool blue is an accent role, not a dominant-fill mandate. Asymmetrical arms have no mandatory length recipe. These are future contract clarifications, not a request for another generation.",
  "width": 16,
  "height": 16,
  "no_background": true
}
import type { QueueState } from "./queue";
export const statusVisuals = {
  idle: { label: "Start", path: "assets/start.svg", frames: 1 },
  running: { label: "Working", path: "assets/working.png", frames: 4 },
  paused: { label: "Paused", path: "assets/paused.png", frames: 1 },
  succeeded: { label: "Ready", path: "assets/ready-confirmed.png", frames: 1 },
  failed: { label: "Retry", path: "assets/error-retry.png", frames: 1 },
};
export const display = { cell: [16, 16], scale: 3, filter: "nearest", frameMs: 100, background: "#172336" };
export function statusCell(state: QueueState) { return statusVisuals[state]; }
export function compactStatus(state: QueueState) { return statusVisuals[state]; }
export function accountBadge(registry: Record<string, string>, account: string) {
  return registry[account]; // Provided by the service; not enumerable in this checkout.
}
export type QueueState = "idle" | "running" | "succeeded" | "failed" | "paused";
export function stateAfter(result: "started" | "ok" | "error" | "pause"): QueueState {
  return { started: "running", ok: "succeeded", error: "failed", pause: "paused" }[result] as QueueState;
}
